components-button--primary.snippet:
import { Component } from '@angular/core';
import { ButtonComponent } from './button.component';

@Component({
  selector: 'app-demo',
  imports: [ButtonComponent],
  template: `
    <button
        dma-button
        type="button"
        [variant]="variant"
        [disabled]="disabled">
        {{ label }}
    </button>`,
})
export class DemoComponent {
  label = 'Save map';
  variant = 'primary';
  disabled = false;
}

